1147:export async function setRate(page: Page, f: { grade: string; pct: string; from?: string; to?: string }): Promise<boolean> {
1148:  await page.getByTestId('rate-form-grade').selectOption(f.grade);
1149:  await page.getByTestId('rate-form-pct').fill(f.pct);
1150:  await setField(page, 'rate-form-from', f.from);
1151:  await setField(page, 'rate-form-to', f.to);
1152:  const r = page.getByTestId(`rate-row-${f.grade}-${f.from ?? 'start'}`);
1153:  const done = async () => (await r.count()) > 0 && await shown(r.getByTestId('rate-pct')) === f.pct
1154:    && (f.to === undefined || await shown(r.getByTestId('rate-to')) === f.to);
1156:  await page.getByTestId('rate-form-submit').click();
1157:  return until(page, done, page.getByTestId('rate-form-error'), 'set rate', already);
